import canonical from "../data/svara-synaptic-contacts-0.1.json";
export const SVARA_CONTACTS: typeof canonical;
export type SvaraContactSelection = { group: string; pre: string; post: string };
export type SvaraContactProof = Readonly<{ group: string }>;
export type SvaraContactRow = { sourceRow: number; pre: string; post: string; areaText: string };
export type SvaraContactData = { group: string; matrix: { componentId: string; sheet: string; sha256: string; pre: string[]; post: string[]; values: string[][] }; contacts: { componentId: string; sheet: string; sha256: string; rows: SvaraContactRow[] } };
export type SvaraContactPair = { selection: SvaraContactSelection; matrixCell: string; matrixSourceText: string; contacts: SvaraContactRow[]; derivedContactCount: number; derivedContactAreaSumUm2: number; matrixSumAbsoluteDifference: number };
export const SVARA_CONTACT_DEFAULT: SvaraContactSelection;
export function svaraContactGroup(group: string): typeof canonical.groups[number];
export function inspectSvaraContactSelection(selection: unknown): SvaraContactSelection;
export function verifySvaraContacts(bytes: Uint8Array, group: string, options?: { signal?: AbortSignal }): Promise<SvaraContactProof>;
export function loadSvaraContacts(group: string, options?: { signal?: AbortSignal; fetchImpl?: typeof fetch }): Promise<SvaraContactProof>;
export function svaraVerifiedContactData(proof: SvaraContactProof, group: string): SvaraContactData;
export function svaraVerifiedContactBytes(proof: SvaraContactProof, group: string): Uint8Array<ArrayBuffer>;
export function svaraContactPair(proof: SvaraContactProof, selection: SvaraContactSelection): SvaraContactPair;
export function buildSvaraContactReceipt(proof: SvaraContactProof, selection: SvaraContactSelection, generatedAt?: string): Record<string, unknown>;
export function inspectSvaraContactReceipt(receipt: unknown): SvaraContactSelection;
export function restoreSvaraContactReceipt(receipt: unknown, proof: SvaraContactProof): SvaraContactSelection;
export function svaraContactCsv(proof: SvaraContactProof, selection: SvaraContactSelection): string;
export function readSvaraContactLocation(href: string): { selection: SvaraContactSelection | null; refusal: string | null };
export function writeSvaraContactLocation(href: string, selection: SvaraContactSelection): string;
export function svaraContactLink(selection: SvaraContactSelection): string;
